package com.ccb.datamigration.service;
import com.ccb.common.exception.*; import java.util.*; import org.springframework.stereotype.Repository;
@Repository public class TopicRepository { private final TopicMapper mapper; public TopicRepository(TopicMapper mapper){this.mapper=mapper;} public long count(Map<String,Object> p){Long n=mapper.count(p);return n==null?0:n;} public List<Map<String,Object>> list(Map<String,Object> p){return mapper.list(p);} public Map<String,Object> require(long t,long id){return required(mapper.find(t,id),"专题不存在");} public Map<String,Object> requireDeleted(long t,long id){return required(mapper.findDeleted(t,id),"专题不存在于回收站");} public Map<String,Object> requireRaw(long t,long id){return required(mapper.findRaw(t,id),"专题不存在");} public void insert(Map<String,Object> p){mapper.insert(p);} public int update(Map<String,Object> p){return mapper.update(p);} public int softDelete(long t,long id,long actor){return mapper.softDelete(t,id,actor);} public int restore(long t,long id,long actor){return mapper.restore(t,id,actor);} public int purge(long t,long id){return mapper.purge(t,id);} public void replaceSystems(long t,long id,long project,List<String> codes,long actor){mapper.deleteSystemRelations(t,id);for(String code:codes){Map<String,Object> p=new LinkedHashMap<>();p.put("id",System.currentTimeMillis()*1000+new java.util.Random().nextInt(1000));p.put("tenantId",t);p.put("topicId",id);p.put("projectId",project);p.put("systemCode",code);p.put("actorId",actor);mapper.insertSystemRelation(p);}} public List<String> systemCodes(long t,long id){return mapper.systemCodes(t,id);} public boolean enabledComponent(long t,long p,String code){Integer n=mapper.enabledComponentCount(t,p,code);return n!=null&&n>0;} public Set<Long> boundAttachmentIds(long t,long id){return new LinkedHashSet<>(mapper.boundAttachmentIds(t,id));} public List<Long> mainAttachmentIds(long t,long id){return mapper.mainAttachmentIds(t,id);} public long requireDeletedProject(long t,long id){List<Long> ids=mapper.deletedProjectIds(t,id);if(ids.isEmpty())throw new BusinessException(ErrorCode.BAD_REQUEST,"专题不存在于回收站");return ids.get(0);} public void audit(long t,long a,long p,String op,long id){mapper.insertAudit(t,a,p,op,id);} private Map<String,Object> required(List<Map<String,Object>> r,String m){if(r.isEmpty())throw new BusinessException(ErrorCode.BAD_REQUEST,m);return r.get(0);} }
